type View="all"|"untried"|"tried"|"categories"|"tools"|"settings"|"trash";
export const shouldNavigateAfterAuthentication=(previous:boolean|null,current:boolean)=>previous===false&&current;
const blank=(status:Recipe["status"]="untried"):Recipe=>({id:uid(),name:"",status,description:"",ingredients:[],steps:[],categoryIds:[],tagIds:[],sourceType:"manual",sourceUrl:"",rawText:"",normalizedText:"",coverImageId:null,createdAt:now(),updatedAt:now(),deletedAt:null,syncStatus:"local_only",revision:0});
