function parseInitialView():View|null{
 const hashRaw=window.location.hash.startsWith("#")?window.location.hash.slice(1):window.location.hash;
 if(!hashRaw)return null;
 const [hashPathRaw,hashQuery]=hashRaw.toLowerCase().split("?");
  const hashPath=hashPathRaw.replace(/^\/+|\/+$/g,"");
 const hashParamsAll=new URLSearchParams(hashRaw);
 const hashType=hashParamsAll.get("type");
 if(hashType==="recovery"&&!hashParamsAll.get("access_token")&&!hashParamsAll.get("error_code"))return"settings";
 const hashView=(hashParamsAll.get("view")||hashParamsAll.get("tab")||"").toLowerCase();
 if(hashPath==="settings"||hashPath==="setting")return"settings";
 if(hashPath==="all")return"all";
 if(hashPath==="untried")return"untried";
 if(hashPath==="tried")return"tried";
 if(hashPath==="categories")return"categories";
 if(hashPath==="tools")return"tools";
 if(hashPath==="trash")return"trash";
  if(hashPath==="")return"all";
  if(hashView==="settings"||hashView==="setting")return"settings";
  if(hashView==="untried"||hashView==="tried"||hashView==="categories"||hashView==="tools"||hashView==="trash")return hashView;
  if(hashView==="all")return"all";
  if(hashPath==="recovery"){
   const params=new URLSearchParams(hashQuery||"");
   if(!params.get("access_token")&&!params.get("error_code"))return"settings";
 }
 if(hashRaw.includes("?")||hashRaw.includes("&")){
  const params=new URLSearchParams(hashQuery||"");
  const fromHash=params.get("view")||params.get("tab")||"";
  if(fromHash==="settings"||fromHash==="setting")return"settings";
  if(fromHash==="all")return"all";
  if(fromHash==="untried"||fromHash==="tried"||fromHash==="categories"||fromHash==="tools"||fromHash==="trash")return fromHash;
  }

 const path=window.location.pathname.toLowerCase();
 if(path.endsWith("/settings")||path.endsWith("/setting"))return"settings";
 if(path.endsWith("/untried"))return"untried";
 if(path.endsWith("/tried"))return"tried";
 if(path.endsWith("/categories"))return"categories";
 if(path.endsWith("/tools"))return"tools";
 if(path.endsWith("/trash"))return"trash";
 if(path.endsWith("/all")||path==="/")return"all";

 const search=new URLSearchParams(window.location.search);
 const fromSearch=(search.get("view")||search.get("tab")||"").toLowerCase();
 if(fromSearch==="settings"||fromSearch==="setting")return"settings";
 if(fromSearch==="all"||fromSearch==="")return"all";
 if(fromSearch==="untried")return"untried";
 if(fromSearch==="tried")return"tried";
 if(fromSearch==="categories")return"categories";
 if(fromSearch==="tools")return"tools";
 if(fromSearch==="trash")return"trash";
 return null;
}

function viewToHash(view:View):string{
 if(view==="all")return "#/";
 if(view==="untried")return "#/untried";
 if(view==="tried")return "#/tried";
 if(view==="categories")return "#/categories";
 if(view==="tools")return "#/tools";
 if(view==="settings")return "#/settings";
 return "#/trash";
}

 export default function App(){
 const recipes=useLiveQuery(()=>db.recipes.orderBy("updatedAt").reverse().toArray(),[])??[];
 const categories=useLiveQuery(()=>db.categories.orderBy("sortOrder").toArray(),[])??[];
 const tags=useLiveQuery(()=>db.tags.toArray(),[])??[];
 const records=useLiveQuery(()=>db.cookRecords.filter(x=>!x.deletedAt).toArray(),[])??[];
 const [view,setView]=useState<View>("all"),[query,setQuery]=useState(""),[showFilters,setShowFilters]=useState(false),[editing,setEditing]=useState<Recipe|null>(null),[detail,setDetail]=useState<Recipe|null>(null);
 const [catFilter,setCatFilter]=useState(""),[tagFilter,setTagFilter]=useState(""),[recordFilter,setRecordFilter]=useState("all");
 const navigateTo=(next:View)=>{
  setDetail(null);
  setEditing(null);
  setView(next);
  const hash=viewToHash(next);
  if(window.location.hash!==hash){
    try {
      window.history.pushState({}, "", hash);
      window.location.hash=hash;
      if(window.location.hash!==hash){
        window.location.assign(hash);
      }
    } catch{
      window.location.assign(hash);
    }
  }
 };
 useEffect(()=>{setDetail(null);setEditing(null)},[view]);
 const openNewRecipe=()=>{setDetail(null);try{const saved=localStorage.getItem(newRecipeDraftKey);setEditing(saved?JSON.parse(saved).recipe:blank())}catch{setEditing(blank())}};
 useEffect(()=>{try{const saved=localStorage.getItem(newRecipeDraftKey);if(saved)setEditing(JSON.parse(saved).recipe)}catch{localStorage.removeItem(newRecipeDraftKey)}},[]);
 const visible=useMemo(()=>{const filtered=recipes.filter(r=>{if(view==="trash")return!!r.deletedAt;if(r.deletedAt)return false;if((view==="untried"||view==="tried")&&r.status!==view)return false;if(catFilter&&!r.categoryIds.includes(catFilter))return false;if(tagFilter&&!r.tagIds.includes(tagFilter))return false;const rr=records.filter(x=>x.recipeId===r.id);if(recordFilter==="has"&&!rr.length)return false;if(recordFilter==="best"&&!rr.some(x=>x.isBestVersion))return false;const text=[r.name,r.description,r.rawText,r.normalizedText,...r.ingredients.flatMap(x=>[x.originalText,x.normalizedText]),...r.steps.flatMap(x=>[x.originalText,x.normalizedText]),...categories.filter(x=>r.categoryIds.includes(x.id)).map(x=>x.name),...tags.filter(x=>r.tagIds.includes(x.id)).map(x=>x.name)].join(" ").toLowerCase();return text.includes(query.toLowerCase())});if(recordFilter==="recentAdded")return filtered.sort((a,b)=>b.createdAt.localeCompare(a.createdAt));if(recordFilter==="recentCooked")return filtered.sort((a,b)=>(records.filter(x=>x.recipeId===b.id).sort((x,y)=>y.cookedAt.localeCompare(x.cookedAt))[0]?.cookedAt??"").localeCompare(records.filter(x=>x.recipeId===a.id).sort((x,y)=>y.cookedAt.localeCompare(x.cookedAt))[0]?.cookedAt??""));return filtered},[recipes,records,categories,tags,view,query,catFilter,tagFilter,recordFilter]);
 useEffect(()=>{const run=()=>import("./services/sync").then(async({getState,syncNow})=>{const s=await getState();if(s.onboardingComplete&&!s.paused)await syncNow()}).catch(()=>undefined);addEventListener("online",run);run();return()=>removeEventListener("online",run)},[]);
 useEffect(()=>{
  const applyCurrentView=()=>{
   const initialView=parseInitialView();
   if(initialView)setView(initialView);
  };
  applyCurrentView();
  addEventListener("hashchange", applyCurrentView);
  addEventListener("popstate", applyCurrentView);
  return()=>{removeEventListener("hashchange", applyCurrentView);removeEventListener("popstate", applyCurrentView);}
},[]);
 const recipeView=(["all","untried","tried"] as View[]).includes(view);
 return <main className="app"><PageHeader title={recipeView?undefined:view==="trash"?"回收站":view==="categories"?"分类与标签":view==="tools"?"厨房工具":"设置"} actions={recipeView?<><IconButton label="搜索" onClick={()=>document.getElementById("recipe-search")?.focus()}><Icon name="search"/></IconButton><IconButton label="筛选" onClick={()=>setShowFilters(x=>!x)}><Icon name="filter"/></IconButton><IconButton primary label="新增食谱" onClick={openNewRecipe}><Icon name="add"/></IconButton></>:undefined}/>
 {(["all","untried","tried"] as View[]).includes(view)&&<SegmentedControl value={view as "all"|"untried"|"tried"} label="食谱状态" items={[{value:"all",label:"全部"},{value:"untried",label:"没做过"},{value:"tried",label:"做过"}]} onChange={value=>navigateTo(value)}/>}
 {recipeView&&<><section className="toolbar"><label className="search"><Icon name="search"/><input id="recipe-search" value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索食谱、食材、标签……"/></label></section>{showFilters&&<section className="filters"><select aria-label="筛选分类" value={catFilter} onChange={e=>setCatFilter(e.target.value)}><option value="">全部分类</option>{categories.filter(x=>!x.deletedAt).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select><select aria-label="筛选标签" value={tagFilter} onChange={e=>setTagFilter(e.target.value)}><option value="">全部标签</option>{tags.filter(x=>!x.deletedAt).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select><select aria-label="筛选制作记录" value={recordFilter} onChange={e=>setRecordFilter(e.target.value)}><option value="all">全部记录</option><option value="has">有制作记录</option><option value="best">有最佳版本</option><option value="recentAdded">最近添加</option><option value="recentCooked">最近制作</option></select></section>}</>}
 {view==="categories"?<TaxonomyManager categories={categories} tags={tags} recipes={recipes}/>:view==="tools"?<Suspense fallback={<section className="content"><p>正在加载厨房工具…</p></section>}><KitchenTools/></Suspense>:view==="settings"?<Settings onTrash={()=>navigateTo("trash")} onAuthenticated={()=>navigateTo("all")}/>:view==="trash"?<Trash recipes={visible}/>:<RecipeGrid recipes={visible} categories={categories} tags={tags} records={records} onOpen={setDetail} onAdd={openNewRecipe}/>}
 <BottomNavigation value={recipeView?"all":view} items={[{value:"all",label:"食谱",icon:<Icon name="recipes"/>,href:viewToHash("all")},{value:"categories",label:"分类",icon:<Icon name="categories"/>,href:viewToHash("categories")},{value:"tools",label:"厨房工具",icon:<Icon name="tools"/>,href:viewToHash("tools")},{value:"settings",label:"设置",icon:<Icon name="settings"/>,href:viewToHash("settings")}]} onChange={navigateTo}/>
 {editing&&(recipes.some(r=>r.id===editing.id)?<RecipeEditor recipe={editing} categories={categories.filter(x=>!x.deletedAt)} tags={tags.filter(x=>!x.deletedAt)} onClose={()=>setEditing(null)} onSaved={r=>{setEditing(null);setDetail(r)}}/>:<NewRecipeFlow recipe={editing} categories={categories.filter(x=>!x.deletedAt)} tags={tags.filter(x=>!x.deletedAt)} onClose={()=>{localStorage.removeItem(newRecipeDraftKey);setEditing(null)}} onSaved={setEditing}/>)}
 {detail&&<RecipeDetail recipeId={detail.id} categories={categories} tags={tags} onClose={()=>setDetail(null)} onEdit={r=>{setDetail(null);setEditing(r)}}/>}
 </main>
}

function RecipeGrid({recipes,categories,tags,records,onOpen,onAdd}:{recipes:Recipe[];categories:Taxonomy[];tags:Taxonomy[];records:CookRecord[];onOpen:(r:Recipe)=>void;onAdd:()=>void}){const [sort,setSort]=useState<"updated"|"created"|"cooked"|"name">("updated"),sortMenuRef=useRef<HTMLDetailsElement>(null),labels={pending:"待同步",error:"同步失败",conflict:"有冲突"},cookedAt=(recipeId:string)=>records.filter(x=>x.recipeId===recipeId&&!x.deletedAt).reduce((latest,record)=>record.cookedAt>latest?record.cookedAt:latest,"");const sorted=[...recipes].sort((a,b)=>sort==="name"?a.name.localeCompare(b.name,"zh-CN"):sort==="created"?b.createdAt.localeCompare(a.createdAt):sort==="cooked"?cookedAt(b.id).localeCompare(cookedAt(a.id)):b.updatedAt.localeCompare(a.updatedAt)),sortLabels={updated:"按更新时间 ↓",created:"按添加时间 ↓",cooked:"按制作时间 ↓",name:"按名称"},chooseSort=(value:typeof sort)=>{setSort(value);if(sortMenuRef.current)sortMenuRef.current.open=false};return <section className="content"><div className="section-title recipe-list-title"><h2>食谱 <span>{recipes.length}</span></h2><details className="sort-menu" ref={sortMenuRef}><summary aria-label="食谱排序">{sortLabels[sort]}</summary><div role="menu"><button type="button" role="menuitem" aria-current={sort==="updated"} onClick={()=>chooseSort("updated")}>最近更新</button><button type="button" role="menuitem" aria-current={sort==="created"} onClick={()=>chooseSort("created")}>最近添加</button><button type="button" role="menuitem" aria-current={sort==="cooked"} onClick={()=>chooseSort("cooked")}>最近制作</button><button type="button" role="menuitem" aria-current={sort==="name"} onClick={()=>chooseSort("name")}>名称</button></div></details></div>{!recipes.length?<div className="empty"><Icon name="recipes"/><b>这里还没有食谱</b><p>上传截图、粘贴文字或手动添加第一份食谱</p><button type="button" className="primary action" onClick={onAdd}>新增食谱</button></div>:<div className="grid">{sorted.map(r=>{const rr=records.filter(x=>x.recipeId===r.id&&!x.deletedAt),categoryNames=categories.filter(x=>r.categoryIds.includes(x.id)).map(x=>x.name),tagNames=tags.filter(x=>r.tagIds.includes(x.id)).map(x=>x.name),abnormal=["pending","error","conflict"].includes(r.syncStatus)?labels[r.syncStatus as keyof typeof labels]:null;return <article key={r.id} className="card"><button className="card-open" onClick={()=>onOpen(r)}><RecipeCover recipe={r} records={rr}/><div className="card-body"><h3>{r.name}</h3><div className="card-taxonomy">{(categoryNames.length?categoryNames:["未分类"]).map(name=><span key={`c-${name}`}>{name}</span>)}</div>{!!tagNames.length&&<div className="card-tags">{tagNames.map(name=><span key={`t-${name}`}>#{name}</span>)}</div>}<footer><time>{new Date(r.updatedAt).toLocaleDateString("zh-CN",{month:"short",day:"numeric"})}</time><span>{rr.length?`制作 ${rr.length} 次`:"未记录制作"}</span>{abnormal&&<span className="sync-warning">{abnormal}</span>}</footer></div></button><details className="card-menu"><summary aria-label={`${r.name}更多操作`}>···</summary><div><button type="button" onClick={()=>onOpen(r)}>查看详情</button></div></details></article>})}</div>}</section>}
function RecipeCover({recipe,records}:{recipe:Recipe;records:CookRecord[]}){const best=records.find(x=>x.isBestVersion);const imageId=best?.coverImageId||recipe.coverImageId;const image=useLiveQuery(()=>imageId?db.images.get(imageId):undefined,[imageId]);return <div className="cover">{image&&!image.deletedAt?<BlobImage blob={image.thumbnailBlob} remoteId={image.remoteThumb?image.id:undefined} variant="thumb" alt={recipe.name}/>:<span className="placeholder"><Icon name="recipes"/></span>}<i>{recipe.status==="tried"?"做过":"没做过"}</i></div>}
function BlobImage({blob,remoteId,variant="full",alt}:{blob:Blob;remoteId?:string;variant?:"full"|"thumb";alt:string}){const [url,setUrl]=useState("");useEffect(()=>{let active=true,current="";async function load(){const value=blob.size?blob:remoteId?await import("./services/sync").then(({fetchRemoteImage})=>fetchRemoteImage(remoteId,variant)):null;if(value&&active){current=URL.createObjectURL(value);setUrl(current)}}load().catch(()=>setUrl(""));return()=>{active=false;if(current)URL.revokeObjectURL(current)}},[blob,remoteId,variant]);return url?<img src={url} alt={alt}/>:null}

type NewRecipeMethod="screenshots"|"paste"|"manual"|"photo";
function NewRecipeFlow({recipe,categories,tags,onClose,onSaved}:{recipe:Recipe;categories:Taxonomy[];tags:Taxonomy[];onClose:()=>void;onSaved:(recipe:Recipe)=>void}){
 const savedDraft=useMemo(()=>{try{return JSON.parse(localStorage.getItem(newRecipeDraftKey)||"null") as {method:NewRecipeMethod|null;stage:"choose"|"input"|"review"}|null}catch{return null}},[]);
 const [value,setValue]=useState(recipe),[method,setMethod]=useState<NewRecipeMethod|null>(savedDraft?.method??null),[stage,setStage]=useState<"choose"|"input"|"review">(savedDraft?.stage??"choose"),[error,setError]=useState(""),[busy,setBusy]=useState(false),[parserResult,setParserResult]=useState<RecipeParserResult|null>(null),[aiDraft,setAiDraft]=useState<AiRecipeDraft|null>(null),[aiBusy,setAiBusy]=useState(false);
 const images=useLiveQuery(()=>db.images.where("recipeId").equals(recipe.id).filter(x=>!x.deletedAt).toArray(),[recipe.id])??[];
 useEffect(()=>{localStorage.setItem(newRecipeDraftKey,JSON.stringify({recipe:value,method,stage}))},[value,method,stage]);
 const setMethodAndStart=(next:NewRecipeMethod)=>{setMethod(next);setStage(next==="manual"?"review":"input");setValue(current=>({...current,status:"untried",sourceType:next==="screenshots"?"screenshot":next==="paste"?"text":next==="photo"?"photo":"manual",ingredients:current.ingredients.length?current.ingredients:[{id:uid(),originalText:"",normalizedText:"",sortOrder:0}],steps:current.steps.length?current.steps:[{id:uid(),originalText:"",normalizedText:"",sortOrder:0}]}))};
 async function uploads(files:FileList|null,type:ImageType){if(!files?.length)return;setBusy(true);try{const existing=await db.images.where("recipeId").equals(value.id).filter(image=>!image.deletedAt&&image.type===type).sortBy("sortOrder"),start=(existing.at(-1)?.sortOrder??-1)+1;for(const [index,file] of [...files].entries()){const processed=await processImage(file,{recipeId:value.id,type,sortOrder:start+index}),image=type==="source"?{...processed,note:file.name}:processed;await saveImage(image);if(type==="source")await getOrCreateOcrRecord(value.id,image.id);if(type==="cover"&&!value.coverImageId)setValue(current=>({...current,coverImageId:image.id}))}}catch(error){setError(error instanceof Error?error.message:"图片保存失败")}finally{setBusy(false)}}
 async function continueFlow(){if(method==="paste"){if(!value.rawText.trim()){setError("请先粘贴食谱文字");return}const {parseRecipeText}=await import("./services/recipe-parser");setParserResult(parseRecipeText(value.rawText))}if(method==="screenshots"&&!images.length){setError("请先选择至少一张截图");return}if(method==="photo"&&!images.length){setError("请先拍摄一张照片");return}setError("");setStage("review")}
 async function acceptParser(){if(!parserResult)return;const {appendConfirmedParserResult}=await import("./services/recipe-parser");setValue(current=>appendConfirmedParserResult(current,parserResult,!current.name.trim(),uid))}
 async function smartOrganize(){if(!value.rawText.trim()||!confirm("智能整理会将你确认的文字发送到 OpenAI，可能产生少量 API 费用。原始图片不会发送。是否继续？"))return;setAiBusy(true);setError("");try{const {createAiDraft}=await import("./services/ai");setAiDraft(await createAiDraft(value.rawText,new AbortController().signal))}catch(error){setError(error instanceof Error?error.message:"智能整理失败；可以继续手动整理")}finally{setAiBusy(false)}}
 async function save(){const cleaned={...value,status:"untried" as const,ingredients:value.ingredients.filter(item=>item.originalText.trim()).map((item,index)=>({...item,normalizedText:enhanceUnits(item.originalText),sortOrder:index})),steps:value.steps.filter(item=>item.originalText.trim()).map((item,index)=>({...item,normalizedText:enhanceUnits(item.originalText),sortOrder:index}))};if(!cleaned.name.trim()){setError("请填写食谱名称");return}setBusy(true);try{const saved=await saveRecipe(cleaned);localStorage.removeItem(newRecipeDraftKey);onSaved(saved)}catch(error){setError(error instanceof Error?error.message:"保存失败，请稍后再试")}finally{setBusy(false)}}
 const stepLabel=stage==="choose"?"选择添加方式":stage==="input"?"第 2 步":"最后确认";
 return <div className="sheet-backdrop"><div className="sheet full new-recipe-flow"><div className="creation-head"><button type="button" onClick={onClose}>取消</button><div><h2>新增食谱</h2><span>{stepLabel}</span></div><span/></div>
 {stage==="choose"?<section className="method-picker" aria-label="选择添加方式"><button type="button" onClick={()=>setMethodAndStart("screenshots")}><Icon name="upload"/><span><b>上传截图</b><small>支持一次选择多张</small></span></button><button type="button" onClick={()=>setMethodAndStart("paste")}><Icon name="recipes"/><span><b>粘贴文字</b><small>保留原始食谱文字</small></span></button><button type="button" onClick={()=>setMethodAndStart("manual")}><Icon name="add"/><span><b>手动输入</b><small>直接填写名称、食材和步骤</small></span></button><button type="button" onClick={()=>setMethodAndStart("photo")}><Icon name="camera"/><span><b>拍照</b><small>拍摄封面后继续填写</small></span></button></section>:stage==="input"?<section className="capture-step">{method==="screenshots"&&<><Upload label="食谱截图" pickerLabel="选择照片或文件" libraryOnly onFiles={files=>uploads(files,"source")}/><ScreenshotList images={images.filter(image=>image.type==="source")}/></>}{method==="paste"&&<label>粘贴食谱文字<textarea autoFocus value={value.rawText} onChange={event=>setValue({...value,rawText:event.target.value})} placeholder="粘贴名称、食材和步骤……"/></label>}{method==="photo"&&<><Upload label="拍摄食谱封面" captureOnly onFiles={files=>uploads(files,"cover")}/><ImageStrip images={images.filter(image=>image.type==="cover")} onDelete={deleteImage} onCover={id=>setValue({...value,coverImageId:id})}/></>}</section>:<section className="creation-review">{method==="screenshots"&&<><ScreenshotList images={images.filter(image=>image.type==="source")}/><OcrSources images={images.filter(image=>image.type==="source")} recipe={value} onRecipeChange={setValue} draftMode/></>}{method==="paste"&&<><details className="source-preview"><summary>查看粘贴的原文</summary><pre>{value.rawText}</pre></details><div className="structure-actions"><button type="button" onClick={smartOrganize} disabled={aiBusy}>{aiBusy?"正在智能整理…":"智能整理"}</button></div>{aiDraft&&<AiDraftPreview draft={aiDraft} onChange={setAiDraft} onAccept={(draft,selected)=>import("./services/ai").then(({applyAiDraft})=>setValue(current=>applyAiDraft(current,draft,selected,uid)))} onDiscard={()=>setAiDraft(null)}/>} {parserResult&&<ParserPreview result={parserResult} useTitle={!value.name.trim()} onUseTitle={()=>undefined} onChange={setParserResult} onConfirm={acceptParser}/>}</>}<CreationFields value={value} onChange={setValue} categories={categories} tags={tags}/>{method==="manual"&&<><Upload label="封面图片（可选）" libraryOnly onFiles={files=>uploads(files,"cover")}/><ImageStrip images={images.filter(image=>image.type==="cover")} onDelete={deleteImage} onCover={id=>setValue({...value,coverImageId:id})}/></>}{method==="photo"&&<ImageStrip images={images.filter(image=>image.type==="cover")} onDelete={deleteImage} onCover={id=>setValue({...value,coverImageId:id})}/>}</section>}
 {error&&<p className="error creation-error">{error}</p>}{stage!=="choose"&&<div className="creation-actions"><button type="button" onClick={()=>stage==="review"?setStage(method==="manual"?"choose":"input"):setStage("choose")}>返回</button>{stage==="input"?<button type="button" className="primary" disabled={busy} onClick={continueFlow}>继续</button>:<button type="button" className="primary" disabled={busy} onClick={save}>{busy?"保存中…":"保存"}</button>}</div>}</div></div>
}

