function ParserPreview({result,useTitle,onUseTitle,onChange,onConfirm}:{result:RecipeParserResult;useTitle:boolean;onUseTitle:(value:boolean)=>void;onChange:(value:RecipeParserResult)=>void;onConfirm:()=>void}){
 const update=async(id:string,changes:Partial<Pick<ParserLine,"normalizedLine"|"detectedType">>)=>{const {updateParserLine}=await import("./services/recipe-parser");onChange(updateParserLine(result,id,changes))};
 const move=async(id:string,direction:-1|1)=>{const {moveParserLine}=await import("./services/recipe-parser");onChange(moveParserLine(result,id,direction))};
 return <section className="parser-preview"><h3>结构化解析预览</h3><p>低置信度内容标为“请确认”。调整完成后再导入，不会覆盖已有食材、步骤或原文。</p><div className="parser-bucket"><h4>建议标题</h4>{result.suggestedTitle?<><label><input type="checkbox" checked={useTitle} onChange={e=>onUseTitle(e.target.checked)}/>采用建议标题{recipeTitleWarning(useTitle)}</label><ParserLineEditor line={result.suggestedTitle} onUpdate={update} onMove={move}/></>:<p>未识别到建议标题</p>}</div><ParserBucket title="食材" lines={result.ingredients} onUpdate={update} onMove={move}/><ParserBucket title="步骤" lines={result.steps} onUpdate={update} onMove={move}/><ParserBucket title="其他 / 待确认" lines={result.unknown} onUpdate={update} onMove={move}/><button type="button" className="primary action" onClick={onConfirm}>确认并追加到食谱</button></section>
}
const recipeTitleWarning=(selected:boolean)=>selected?"（会采用当前建议）":"";
function ParserBucket({title,lines,onUpdate,onMove}:{title:string;lines:ParserLine[];onUpdate:(id:string,changes:Partial<Pick<ParserLine,"normalizedLine"|"detectedType">>)=>void;onMove:(id:string,direction:-1|1)=>void}){return <div className="parser-bucket"><h4>{title}</h4>{lines.length?lines.map(line=><ParserLineEditor key={line.id} line={line} onUpdate={onUpdate} onMove={onMove}/>):<p>暂无内容</p>}</div>}
function ParserLineEditor({line,onUpdate,onMove}:{line:ParserLine;onUpdate:(id:string,changes:Partial<Pick<ParserLine,"normalizedLine"|"detectedType">>)=>void;onMove:(id:string,direction:-1|1)=>void}){return <div className="parser-line"><input aria-label="解析文字" value={line.normalizedLine} onChange={e=>onUpdate(line.id,{normalizedLine:e.target.value})}/>{line.confidence<.7&&line.detectedType!=="ignored"&&<span className="parser-warning">请确认</span>}<select aria-label="文字分类" value={line.detectedType} onChange={e=>onUpdate(line.id,{detectedType:e.target.value as ParserDetectedType})}><option value="title">标题</option><option value="ingredient">食材</option><option value="step">步骤</option><option value="unknown">待确认</option><option value="ignored">忽略</option></select><button type="button" aria-label="上移解析行" onClick={()=>onMove(line.id,-1)}>↑</button><button type="button" aria-label="下移解析行" onClick={()=>onMove(line.id,1)}>↓</button>{line.detectedType!=="ignored"&&<button type="button" onClick={()=>onUpdate(line.id,{detectedType:"ignored"})}>删除</button>}<small>{line.matchedRules.join(" · ")||"未匹配规则"}</small></div>}

function RecipeDetail({recipeId,categories,tags,onClose,onEdit}:{recipeId:string;categories:Taxonomy[];tags:Taxonomy[];onClose:()=>void;onEdit:(r:Recipe)=>void}){const recipe=useLiveQuery(()=>db.recipes.get(recipeId),[recipeId]);const records=useLiveQuery(()=>db.cookRecords.where("recipeId").equals(recipeId).filter(x=>!x.deletedAt).sortBy("cookedAt"),[recipeId])??[];const [mode,setMode]=useState<"raw"|"enhanced">("enhanced"),[cook,setCook]=useState<CookRecord|null>(null);if(!recipe)return null;const best=records.find(x=>x.isBestVersion);
 return <div className="detail"><div className="detail-top"><button onClick={onClose}>‹ 食谱</button><button onClick={()=>onEdit(recipe)}>编辑</button></div><RecipeCover recipe={recipe} records={records}/><article><h1>{recipe.name}</h1><div className="status"><button className={recipe.status==="untried"?"on":""} onClick={()=>saveRecipe({...recipe,status:"untried"})}>没做过</button><button className={recipe.status==="tried"?"on":""} onClick={()=>saveRecipe({...recipe,status:"tried"})}>做过</button></div><div className="chips">{[...categories.filter(x=>recipe.categoryIds.includes(x.id)),...tags.filter(x=>recipe.tagIds.includes(x.id))].map(x=><span key={x.id}>{x.name}</span>)}</div>
 <div className="mode"><button className={mode==="raw"?"on":""} onClick={()=>setMode("raw")}>原文模式</button><button className={mode==="enhanced"?"on":""} onClick={()=>setMode("enhanced")}>增强模式</button></div>{mode==="raw"?<Raw recipe={recipe}/>:<Enhanced recipe={recipe}/>}
 {best&&<section className="best"><h2>最佳版本 · {best.cookedAt}</h2><p>{best.actualTemperatureC!=null?`${best.actualTemperatureC}℃ / ${best.actualTemperatureF}°F`:"未记录温度"} · {best.actualDurationMinutes??"—"} 分钟</p><p>{best.notes||"没有备注"}</p>{best.coverImageId&&<BestImage id={best.coverImageId}/>}</section>}
 <section><div className="section-title"><h2>制作历史</h2><button className="text-btn" onClick={()=>setCook(emptyCook(recipe.id))}>＋ 新增</button></div>{[...records].sort((a,b)=>b.cookedAt.localeCompare(a.cookedAt)).map(r=><div className="cook" key={r.id}><button onClick={()=>setCook(r)}><b>{r.cookedAt}{r.isBestVersion?" · 最佳版本":""}</b><span>{r.notes||"查看记录"}</span></button></div>)}</section><button className="danger" onClick={async()=>{if(confirm("移到回收站？")){await softDeleteRecipe(recipe.id);onClose()}}}>删除食谱</button></article>{cook&&<CookEditor record={cook} onClose={()=>setCook(null)}/>}</div>}
function Raw({recipe}:{recipe:Recipe}){const sources=useLiveQuery(()=>db.images.where({recipeId:recipe.id,type:"source"}).filter(x=>!x.deletedAt).toArray(),[recipe.id])??[];const records=useLiveQuery(()=>db.ocrRecords.where("recipeId").equals(recipe.id).filter(x=>!x.deletedAt&&!!x.rawOcrText).toArray(),[recipe.id])??[];return <section><h2>原始内容</h2><p className="raw">{recipe.rawText||"没有原文"}</p>{records.map(record=><div key={record.id}><h3>截图识别原文</h3><p className="raw">{record.rawOcrText}</p>{record.editedOcrText!==record.rawOcrText&&<><h3>编辑后的识别文字</h3><p className="raw">{record.editedOcrText}</p></>}</div>)}<ImageStrip images={sources} onDelete={deleteImage}/></section>}
function Enhanced({recipe}:{recipe:Recipe}){return <><section><h2>食材</h2><ul>{recipe.ingredients.map(x=><li key={x.id}>{x.normalizedText||enhanceUnits(x.originalText)}</li>)}</ul></section><section><h2>步骤</h2><ol>{recipe.steps.map(x=><li key={x.id}>{x.normalizedText||enhanceUnits(x.originalText)}</li>)}</ol></section></>}
function BestImage({id}:{id:string}){const image=useLiveQuery(()=>db.images.get(id),[id]);return image&&!image.deletedAt?<div className="best-image"><BlobImage blob={image.blob} remoteId={image.remoteFull?image.id:undefined} alt="最佳版本"/></div>:null}
const emptyCook=(recipeId:string):CookRecord=>({id:"",recipeId,cookedAt:now().slice(0,10),actualTemperatureC:null,actualTemperatureF:null,actualDurationMinutes:null,actualServings:"",ingredientChanges:"",stepChanges:"",notes:"",isBestVersion:false,coverImageId:null,createdAt:"",updatedAt:""});
function CookEditor({record,onClose}:{record:CookRecord;onClose:()=>void}){const [value,setValue]=useState(record),[error,setError]=useState(""),[busy,setBusy]=useState(false);const images=useLiveQuery(()=>record.id?db.images.where("cookRecordId").equals(record.id).filter(x=>!x.deletedAt).toArray():[],[record.id])??[];async function submit(e?:FormEvent){e?.preventDefault?.();if(busy)return;setBusy(true);try{let saved=value;if(!value.id)saved=await addCookRecord({...value,id:undefined,createdAt:undefined,updatedAt:undefined} as never);else await saveCookRecord(value);onClose();return saved}finally{setBusy(false)}}async function upload(files:FileList|null){if(!files)return;let id=value.id;if(!id){const saved=await addCookRecord({...value,id:undefined,createdAt:undefined,updatedAt:undefined} as never);id=saved.id;setValue(saved)}try{setBusy(true);for(const [i,file] of [...files].entries())await saveImage(await processImage(file,{recipeId:value.recipeId,cookRecordId:id,type:"cook_record",sortOrder:images.length+i}))}catch(e){setError(e instanceof Error?e.message:"图片保存失败")}finally{setBusy(false)}}return <div className="sheet-backdrop"><form className="sheet" onSubmit={submit}><div className="sheet-head"><button type="button" onClick={onClose}>取消</button><h2>制作记录</h2><button type="submit" className="save" disabled={busy} onClick={()=>void submit()} onTouchEnd={()=>void submit()}>保存</button></div><label>日期<input type="date" value={value.cookedAt} onChange={e=>setValue({...value,cookedAt:e.target.value})}/></label><label>实际温度 ℃<input type="number" value={value.actualTemperatureC??""} onChange={e=>{const c=e.target.value===""?null:Number(e.target.value);setValue({...value,actualTemperatureC:c,actualTemperatureF:c==null?null:c*9/5+32})}}/></label><label>实际时间（分钟）<input type="number" value={value.actualDurationMinutes??""} onChange={e=>setValue({...value,actualDurationMinutes:e.target.value===""?null:Number(e.target.value)})}/></label><label>实际份量<input value={value.actualServings} onChange={e=>setValue({...value,actualServings:e.target.value})}/></label><label>食材修改<textarea value={value.ingredientChanges} onChange={e=>setValue({...value,ingredientChanges:e.target.value})}/></label><label>步骤修改<textarea value={value.stepChanges} onChange={e=>setValue({...value,stepChanges:e.target.value})}/></label><label>本次备注<textarea value={value.notes} onChange={e=>setValue({...value,notes:e.target.value})}/></label><label className="toggle"><input type="checkbox" checked={value.isBestVersion} onChange={e=>setValue({...value,isBestVersion:e.target.checked})}/>设为最佳版本</label><Upload label="成品图片" capture onFiles={upload}/><ImageStrip images={images} onDelete={deleteImage} onCover={id=>setValue({...value,coverImageId:id})}/>{value.id&&<button type="button" className="danger" onClick={async()=>{if(confirm("删除这次制作记录及图片？")){await deleteCookRecord(value.id);onClose()}}}>删除记录</button>}{error&&<p className="error">{error}</p>}</form></div>}

function TaxonomyManager({categories,tags,recipes}:{categories:Taxonomy[];tags:Taxonomy[];recipes:Recipe[]}){
 const [tab,setTab]=useState<"categories"|"tags">("categories"),[selected,setSelected]=useState<string[]>([]);
 const items=(tab==="categories"?categories:tags).filter(item=>!item.deletedAt).sort((a,b)=>a.sortOrder-b.sortOrder),linkedCount=(item:Taxonomy)=>recipes.filter(recipe=>!recipe.deletedAt&&(tab==="categories"?recipe.categoryIds:recipe.tagIds).includes(item.id)).length;
 async function add(){const label=tab==="categories"?"分类":"标签",name=prompt(`新建${label}`);if(!name?.trim())return;if(tab==="tags"&&(await duplicateTags(name)).length&&!confirm("发现疑似重复标签，仍然创建？"))return;await createTaxonomy(tab,name)}
 async function rename(item:Taxonomy){const name=prompt("新名称",item.name);if(name?.trim()&&name.trim()!==item.name)await renameTaxonomy(tab,item.id,name)}
 async function merge(item:Taxonomy){const targetName=prompt(`将「${item.name}」合并到哪个${tab==="categories"?"分类":"标签"}？`),target=items.find(candidate=>candidate.id!==item.id&&candidate.name===targetName);if(targetName&&!target){alert("没有找到目标");return}if(target&&confirm(`确认将「${item.name}」合并到「${target.name}」？关联食谱会保留。`))await mergeTaxonomy(tab,item.id,target.id)}
 async function remove(item:Taxonomy){const count=linkedCount(item),label=tab==="categories"?"分类":"标签";if(confirm(`「${item.name}」关联 ${count} 份食谱。删除${label}只会解除关联，绝不会删除食谱。继续？`))await deleteTaxonomy(tab,item.id)}
 async function move(index:number,direction:-1|1){if(tab!=="categories")return;const target=index+direction;if(target<0||target>=items.length)return;await swapCategoryOrder(items[index].id,items[target].id)}
 async function batch(addMode:boolean){if(!selected.length){alert("请先选择食谱");return}const name=prompt(addMode?"输入要批量添加的标签名称":"输入要批量移除的标签名称"),tag=tags.find(item=>!item.deletedAt&&item.name===name);if(!tag){alert("没有找到该标签");return}for(const id of selected){const recipe=await db.recipes.get(id);if(!recipe)continue;const tagIds=addMode?[...new Set([...recipe.tagIds,tag.id])]:recipe.tagIds.filter(item=>item!==tag.id);await saveRecipe({...recipe,tagIds})}}
 const emptyTitle=tab==="categories"?"还没有分类":"还没有标签",emptyDescription=tab==="categories"?"创建分类来整理你的食谱":"使用标签记录口味、工具或场景",newLabel=tab==="categories"?"新建分类":"新建标签";
 return <section className="content taxonomy-manager"><div className="taxonomy-head"><SegmentedControl value={tab} label="分类与标签" items={[{value:"categories",label:"分类"},{value:"tags",label:"标签"}]} onChange={value=>{setTab(value);setSelected([])}}/><button type="button" className="primary compact-primary" onClick={add}>＋ {newLabel}</button></div>{tab==="tags"&&recipes.some(recipe=>!recipe.deletedAt)&&<details className="batch-panel taxonomy-batch"><summary>批量管理标签</summary>{recipes.filter(recipe=>!recipe.deletedAt).map(recipe=><label key={recipe.id}><input type="checkbox" checked={selected.includes(recipe.id)} onChange={()=>setSelected(selected.includes(recipe.id)?selected.filter(id=>id!==recipe.id):[...selected,recipe.id])}/>{recipe.name}</label>)}<div><button type="button" onClick={()=>batch(true)}>批量添加</button><button type="button" onClick={()=>batch(false)}>批量移除</button></div></details>}{!items.length?<div className="empty compact-empty taxonomy-empty"><Icon name="categories"/><b>{emptyTitle}</b><p>{emptyDescription}</p><button type="button" className="primary compact-primary" onClick={add}>{newLabel}</button></div>:<div className="taxonomy-list">{items.map((item,index)=><article className="taxonomy-row" key={item.id}>{tab==="categories"&&<span className="order-handle" aria-label="排序位置"><Icon name="drag"/></span>}<div className="taxonomy-name"><b>{item.name}</b><span>{linkedCount(item)} 份食谱</span></div><details className="taxonomy-menu"><summary aria-label={`${item.name}更多操作`}><Icon name="more"/></summary><div><button type="button" onClick={async e=>{e.currentTarget.closest("details")?.removeAttribute("open");await rename(item)}}>改名</button><button type="button" onClick={async e=>{e.currentTarget.closest("details")?.removeAttribute("open");await merge(item)}}>合并</button>{tab==="categories"&&<><button type="button" disabled={index===0} onClick={async e=>{e.currentTarget.closest("details")?.removeAttribute("open");await move(index,-1)}}>上移</button><button type="button" disabled={index===items.length-1} onClick={async e=>{e.currentTarget.closest("details")?.removeAttribute("open");await move(index,1)}}>下移</button></>}<button type="button" className="danger-text" onClick={async e=>{e.currentTarget.closest("details")?.removeAttribute("open");await remove(item)}}>删除</button></div></details></article>)}</div>}</section>
}
async function permanentlyDeleteEverywhere(id:string){const {deleteRemoteRecipe,getState}=await import("./services/sync");const state=await getState();if(state.onboardingComplete&&state.accountEmail)await deleteRemoteRecipe(id);await deleteLocalRecipe(id)}
function Trash({recipes}:{recipes:Recipe[]}){const [selected,setSelected]=useState<string[]>([]);const all=selected.length===recipes.length&&recipes.length>0;async function each(fn:(id:string)=>Promise<void>){try{for(const id of selected)await fn(id);setSelected([])}catch(error){alert(error instanceof Error?`永久删除失败：${error.message}`:"永久删除失败")}}return <section className="content"><div className="trash-actions"><label><input type="checkbox" checked={all} onChange={()=>setSelected(all?[]:recipes.map(r=>r.id))}/>全选</label><button onClick={()=>each(restoreRecipe)} disabled={!selected.length}>批量恢复</button><button onClick={()=>selected.length&&confirm("永久删除所选食谱及全部关联数据？此操作无法撤销。")&&each(permanentlyDeleteEverywhere)} disabled={!selected.length}>永久删除</button><button onClick={()=>recipes.length&&confirm("清空回收站？所有数据和图片将永久删除。")&&Promise.all(recipes.map(r=>permanentlyDeleteEverywhere(r.id))).catch(error=>alert(error instanceof Error?`清空失败：${error.message}`:"清空失败"))}>清空</button></div>{recipes.map(r=><div className="row" key={r.id}><label><input type="checkbox" checked={selected.includes(r.id)} onChange={()=>setSelected(selected.includes(r.id)?selected.filter(x=>x!==r.id):[...selected,r.id])}/><b>{r.name}</b></label><div><button onClick={()=>restoreRecipe(r.id)}>恢复</button><button onClick={()=>confirm("永久删除？此操作无法撤销。")&&permanentlyDeleteEverywhere(r.id).catch(error=>alert(error instanceof Error?`永久删除失败：${error.message}`:"永久删除失败"))}>永久删除</button></div></div>)}</section>}
type SettingsSheet="login"|"password"|"magic"|"conflicts"|null;
