 useEffect(()=>{if(session?.authenticated&&session.requiresPasswordReset){setShowPasswordForm(true);setAuthMode("password");setSheet("password")}},[session?.authenticated,session?.requiresPasswordReset]);
 async function run(){setMessage("正在同步…");try{const {syncNow}=await import("./services/sync"),result=await syncNow();setMessage(`已同步 ${result.synced} 项，错误 ${result.errors} 项，冲突 ${result.conflicts} 项`)}catch{setMessage("已保存在本机，等待云端同步。")}}
 async function makeBackup(share=false){setMessage("正在建立一致性快照…");const backup=await import("./services/backup"),result=await backup.exportBackup(setProgress);if(share)await backup.shareBackup(result.blob,result.filename);else backup.downloadBackup(result.blob,result.filename);const exportedAt=now();localStorage.setItem("pourrecipe-last-export",exportedAt);setLastExport(exportedAt);setProgress(1);setMessage(`备份完成：${result.preview.counts.recipes} 份食谱、${result.preview.counts.images} 张图片、${result.preview.counts.ocrRecords} 条 OCR`);return result}
 async function restore(){if(!backupFile)return;try{setMessage("正在完整验证备份…");const backup=await import("./services/backup"),valid=await backup.validateBackup(backupFile);const choice=prompt(`备份包含 ${valid.preview.counts.recipes} 份食谱、${valid.preview.counts.images} 张图片。输入“合并”或“替换”；其他输入取消。`);const mode=choice==="合并"?"merge":choice==="替换"?"replace":null;if(!mode)return;if(mode==="replace"&&!confirm("替换会先自动生成当前数据安全备份，然后整体替换。确认继续？"))return;const result=await backup.importBackup(valid,mode);if(result.safetyBackup)backup.downloadBackup(result.safetyBackup.blob,result.safetyBackup.filename);setMessage(`导入完成；产生 ${result.conflicts} 个需要处理的同 UUID 冲突。不会自动上传云端。`)}catch(error){setMessage(error instanceof Error?error.message:"导入失败，当前数据未改变")}}
 async function sendMagicLink(){try{const {requestEmailMagicLink}=await import("./services/supabase");await requestEmailMagicLink(email);setMessage("邮箱登录链接已发送。请打开邮件并点击链接返回 PourRecipe。")}catch(error){setMessage(error instanceof Error?error.message:"无法发送邮箱登录链接")}}
 async function signInWithPassword(){if(!email||!password){setMessage("请输入邮箱和密码");return}setAuthBusy(true);try{const {signInWithPassword}=await import("./services/supabase");await signInWithPassword(email,password);setPassword("");setMessage("密码登录成功。")}catch(error){setMessage(error instanceof Error?error.message:"登录失败")}finally{setAuthBusy(false)}}
 async function sendPasswordReset(){if(!email){setMessage("请输入邮箱地址");return}setAuthBusy(true);try{const {requestPasswordReset}=await import("./services/supabase");await requestPasswordReset(email);setMessage("密码重置邮件已发送。请打开邮件并完成设置。")}catch(error){setMessage(error instanceof Error?error.message:"发送密码重置邮件失败")}finally{setAuthBusy(false)}}
 async function sendPasswordResetForSignedIn(){if(!session?.email){setMessage("当前无法识别登录邮箱");return}setAuthBusy(true);try{const {requestPasswordReset}=await import("./services/supabase");await requestPasswordReset(session.email);setMessage("已发送密码重置邮件。请打开邮件并按提示重置。")}catch(error){setMessage(error instanceof Error?error.message:"发送密码重置邮件失败")}finally{setAuthBusy(false)}}
 async function updatePassword(){if(newPassword.length<8){setMessage("新密码长度至少 8 位");return}if(newPassword!==confirmPassword){setMessage("两次输入的密码不一致");return}setAuthBusy(true);try{const {updatePassword}=await import("./services/supabase");await updatePassword(newPassword);setMessage(session?.requiresPasswordReset?"密码已重置，登录已恢复。":"密码已更新。");setNewPassword("");setConfirmPassword("");setShowPasswordForm(false);if(session)setSession({...session,requiresPasswordReset:false})}catch(error){setMessage(error instanceof Error?error.message:"密码更新失败")}finally{setAuthBusy(false)}}
  async function signOut(){try{const {signOut}=await import("./services/supabase");await signOut();setSession({authenticated:false})}catch(error){setMessage(error instanceof Error?error.message:"退出登录失败")}}
